--

CREATE TABLE clinlims.corrective_action (
    id bigint DEFAULT nextval('clinlims.corrective_action_seq'::regclass) NOT NULL,
    freezer_id bigint NOT NULL,
    action_type character varying(50) NOT NULL,
    description text NOT NULL,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    created_by integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by integer,
    updated_at timestamp with time zone,
    is_edited boolean DEFAULT false NOT NULL,
    completed_at timestamp with time zone,
    completion_notes text,
    retracted_at timestamp with time zone,
    retraction_reason text,
    last_updated timestamp without time zone DEFAULT now(),
    CONSTRAINT chk_corrective_action_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'RETRACTED'::character varying])::text[]))),
    CONSTRAINT chk_corrective_action_type CHECK (((action_type)::text = ANY ((ARRAY['TEMPERATURE_ADJUSTMENT'::character varying, 'EQUIPMENT_REPAIR'::character varying, 'SAMPLE_RELOCATION'::character varying, 'CALIBRATION'::character varying, 'ITEM_REORDER'::character varying, 'MAINTENANCE'::character varying, 'OTHER'::character varying])::text[])))
);


