--

CREATE TABLE clinlims.trm_concept_pc_link (
    pid bigint NOT NULL,
    child_pid bigint,
    codesystem_pid bigint NOT NULL,
    parent_pid bigint,
    rel_type integer
);


--
-- Name: trm_concept_property; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.trm_concept_property (
    pid bigint NOT NULL,
    prop_codesystem character varying(500),
    prop_display character varying(500),
    prop_key character varying(500) NOT NULL,
    prop_type integer NOT NULL,
    prop_val character varying(500),
    prop_val_lob oid,
    cs_ver_pid bigint,
    concept_pid bigint
);


--
-- Name: trm_valueset; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.trm_valueset (
    pid bigint NOT NULL,
    expansion_status character varying(50) NOT NULL,
    expanded_at timestamp without time zone,
    vsname character varying(200),
    res_id bigint,
    total_concept_designations bigint DEFAULT 0 NOT NULL,
    total_concepts bigint DEFAULT 0 NOT NULL,
    url character varying(200) NOT NULL,
    ver character varying(200)
);


--
-- Name: trm_valueset_c_designation; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.trm_valueset_c_designation (
    pid bigint NOT NULL,
    valueset_concept_pid bigint NOT NULL,
    lang character varying(500),
    use_code character varying(500),
    use_display character varying(500),
    use_system character varying(500),
    val character varying(2000) NOT NULL,
    valueset_pid bigint NOT NULL
);


--
-- Name: trm_valueset_concept; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.trm_valueset_concept (
    pid bigint NOT NULL,
    codeval character varying(500) NOT NULL,
    display character varying(400),
    index_status bigint,
    valueset_order integer NOT NULL,
    source_direct_parent_pids oid,
    source_pid bigint,
    system_url character varying(200) NOT NULL,
    system_ver character varying(200),
    valueset_pid bigint NOT NULL
);


--
-- Name: type_of_data_indicator; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.type_of_data_indicator (
    id numeric(20,0) NOT NULL,
    name character varying(20) NOT NULL,
    name_key character varying(40),
    description text,
    description_key character varying(40),
    lastupdated timestamp without time zone NOT NULL
);


--
-- Name: type_of_data_indicator_seq; Type: SEQUENCE; Schema: clinlims; Owner: -
--

CREATE SEQUENCE clinlims.type_of_data_indicator_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: type_of_provider; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.type_of_provider (
    id numeric(10,0) NOT NULL,
    description character varying(240),
    tp_code character varying(1)
);


--
-- Name: COLUMN type_of_provider.id; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_provider.id IS 'A unique auto generated integer number assigned by the database.';


--
-- Name: COLUMN type_of_provider.description; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_provider.description IS 'Description such as doctor, nurse, clinician, veteranarian.';


--
-- Name: type_of_sample; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.type_of_sample (
    id numeric(10,0) NOT NULL,
    description character varying(40) NOT NULL,
    domain character varying(1),
    lastupdated timestamp(6) without time zone,
    local_abbrev character varying(10),
    is_active boolean DEFAULT true,
    sort_order numeric DEFAULT 2147483647,
    name_localization_id numeric NOT NULL,
    display_key character varying(60)
);


--
-- Name: COLUMN type_of_sample.id; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_sample.id IS 'A unique auto generated integer number assigned by the database';


--
-- Name: COLUMN type_of_sample.description; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_sample.description IS 'Description such as water, tissue, sludge, etc.';


--
-- Name: COLUMN type_of_sample.domain; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_sample.domain IS 'Type of sample this can be applied to : Environ, Animal, Clinical';


--
-- Name: COLUMN type_of_sample.display_key; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_sample.display_key IS 'Resource file lookup key for localization of displaying the name';


--
-- Name: type_of_sample_seq; Type: SEQUENCE; Schema: clinlims; Owner: -
--

CREATE SEQUENCE clinlims.type_of_sample_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: type_of_test_result; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.type_of_test_result (
    id numeric(10,0) NOT NULL,
    test_result_type character varying(1),
    description character varying(60),
    lastupdated timestamp(6) without time zone,
    hl7_value character varying(20)
);


--
-- Name: COLUMN type_of_test_result.id; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_test_result.id IS 'A unique auto generated integer number assigned by database';


--
-- Name: COLUMN type_of_test_result.test_result_type; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_test_result.test_result_type IS 'Test Result Type (T, N, D)';


--
-- Name: COLUMN type_of_test_result.description; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.type_of_test_result.description IS 'Human readable description';


--
-- Name: type_of_test_result_seq; Type: SEQUENCE; Schema: clinlims; Owner: -
--

CREATE SEQUENCE clinlims.type_of_test_result_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: unit_mapping; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.unit_mapping (
    id character varying(36) NOT NULL,
    analyzer_field_id character varying(36) NOT NULL,
    analyzer_unit character varying(50) NOT NULL,
