    conversion_factor numeric(10,6),
    reject_if_mismatch boolean DEFAULT false NOT NULL,
    sys_user_id character varying(36),
    last_updated timestamp without time zone DEFAULT now() NOT NULL
);


--
-- Name: unit_of_measure; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.unit_of_measure (
    id numeric(10,0) NOT NULL,
    name character varying(26),
    description character varying(60),
    lastupdated timestamp(6) without time zone
);


--
-- Name: COLUMN unit_of_measure.name; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.unit_of_measure.name IS 'Name of Unit';


--
-- Name: COLUMN unit_of_measure.description; Type: COMMENT; Schema: clinlims; Owner: -
--

COMMENT ON COLUMN clinlims.unit_of_measure.description IS 'Description of Unit';


--
-- Name: unit_of_measure_seq; Type: SEQUENCE; Schema: clinlims; Owner: -
--

CREATE SEQUENCE clinlims.unit_of_measure_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: user_alert_map; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.user_alert_map (
    user_id integer NOT NULL,
    alert_id integer,
    report_id integer,
    alert_limit integer,
    alert_operator character varying(255),
    map_id integer NOT NULL
);


--
-- Name: user_group_map; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.user_group_map (
    user_id integer NOT NULL,
    group_id integer NOT NULL,
    map_id integer NOT NULL
);


--
-- Name: user_lab_unit_roles; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.user_lab_unit_roles (
