    last_updated timestamp without time zone
);


--
-- Name: validation_rule_configuration; Type: TABLE; Schema: clinlims; Owner: -
--

CREATE TABLE clinlims.validation_rule_configuration (
    id character varying(36) NOT NULL,
    custom_field_type_id character varying(36) NOT NULL,
    rule_name character varying(100) NOT NULL,
    rule_type character varying(20) NOT NULL,
    rule_expression text,
    error_message character varying(500),
    is_active boolean DEFAULT true NOT NULL,
    sys_user_id character varying(36),
    last_updated timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_rule_type CHECK (((rule_type)::text = ANY ((ARRAY['REGEX'::character varying, 'RANGE'::character varying, 'ENUM'::character varying, 'LENGTH'::character varying])::text[])))
);


